    /** An area: an ellipse around (cx, cz) with half axes rx, rz. */
    public record Gebied4(String id, int cx, int cz, int rx, int rz, int minLevel, int maxLevel, boolean stad) {
        public boolean bevat(double x, double z) {
            double dx = (x - cx) / rx, dz = (z - cz) / rz;
            return dx * dx + dz * dz <= 1.0;
        }

        public String naamKey() {
            return "vadsrijk.kern.gebied." + id;
        }
    }

    /** A boss arena: a cylinder around the stand spot {@code midden}, radius r, from y0 to y1. */
    public record Arena(String id, BlockPos midden, int r, int y0, int y1) {
        public boolean bevat(double x, double y, double z) {
            double dx = x - (midden.getX() + 0.5), dz = z - (midden.getZ() + 0.5);
            return y >= y0 && y <= y1 + 0.999 && dx * dx + dz * dz <= (double) r * r;
        }
    }

    /** A sailboat dock: where you stand at the end of the jetty, and where the boat floats (water surface block). */
